<?php
ob_start(); session_start(); if (!isset($_SESSION['admCodigo'])) { header('Location: login.php'); exit; }
require_once 'classe/conexao.php'; $obj=new Conexao(); $item=$_GET['item']??'listar'; $codigo=filter_input(INPUT_GET,'codigo',FILTER_VALIDATE_INT); $erro='';
if ($_SERVER['REQUEST_METHOD']==='POST' && !Conexao::validarCsrf($_POST['_csrf']??null)) {$erro='Sessão expirada. Recarregue a página.'; $item='listar';}
if (!$erro && $item==='salvar' && $_SERVER['REQUEST_METHOD']==='POST') {
 $id=(int)($_POST['assCodigo']??0); $dados=['valor'=>(float)($_POST['valor']??0),'dias'=>(int)($_POST['dias']??0),'nome'=>trim((string)($_POST['nome']??''))];
 if($dados['nome']===''||$dados['dias']<1||$dados['valor']<0){$erro='Informe nome, dias e valor válidos.';}
 else { $sql=$id?'UPDATE assinatura SET valor=:valor,dias=:dias,nome=:nome WHERE assCodigo=:id':'INSERT INTO assinatura (valor,dias,nome) VALUES (:valor,:dias,:nome)'; if($id)$dados['id']=$id; $ok=$obj->executarPreparado($sql,$dados); if($ok){$obj->registrarLog((int)$_SESSION['admCodigo'],'assinatura',$id?'UPDATE':'INSERT',$id?:null,$sql);header('Location: assinatura.php?sucesso='.($id?'2':'1'));exit;} $erro='Não foi possível salvar a assinatura.';}
}
if(!$erro&&$item==='remover'&&$_SERVER['REQUEST_METHOD']==='POST'){ $ids=array_values(array_filter(array_map('intval',(array)($_POST['assCodigo']??[])))); if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$ok=$obj->executarPreparado("DELETE FROM assinatura WHERE assCodigo IN ($marks)",$ids);if($ok)foreach($ids as $id)$obj->registrarLog((int)$_SESSION['admCodigo'],'assinatura','DELETE',$id);header('Location: assinatura.php?sucesso='.($ok?'3':'4'));exit;}$erro='Selecione ao menos um registro.';}
$registro=['assCodigo'=>'','valor'=>'','dias'=>'','nome'=>'']; if($item==='adicionar'&&$codigo){$r=$obj->consultaPreparada('SELECT assCodigo,valor,dias,nome FROM assinatura WHERE assCodigo=:id',['id'=>$codigo])->fetch();if($r)$registro=array_merge($registro,$r);} function hs($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Assinaturas</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php include 'header.php';?><div class="container-fluid"><div class="row"><aside class="col-2"><?php include 'menu.php';?></aside><main class="col-10"><h1>Assinaturas</h1><?php if($erro):?><div class="alert alert-danger"><?php echo hs($erro);?></div><?php endif;?><?php if($item==='adicionar'):?><form method="post" action="assinatura.php?item=salvar" class="row g-3"><input type="hidden" name="_csrf" value="<?php echo hs(Conexao::csrfToken());?>"><input type="hidden" name="assCodigo" value="<?php echo hs($registro['assCodigo']);?>"><div class="col-md-6"><label class="form-label">Nome</label><input required class="form-control" name="nome" value="<?php echo hs($registro['nome']);?>"></div><div class="col-md-3"><label class="form-label">Valor</label><input required type="number" step="0.01" min="0" class="form-control" name="valor" value="<?php echo hs($registro['valor']);?>"></div><div class="col-md-3"><label class="form-label">Dias</label><input required type="number" min="1" class="form-control" name="dias" value="<?php echo hs($registro['dias']);?>"></div><div class="col-12"><button class="btn btn-primary">Salvar</button></div></form><?php else:?><p><a class="btn btn-primary" href="assinatura.php?item=adicionar">Adicionar assinatura</a></p><form method="post" action="assinatura.php?item=remover"><input type="hidden" name="_csrf" value="<?php echo hs(Conexao::csrfToken());?>"><button class="btn btn-danger mb-3">Remover selecionados</button><table class="table table-hover"><thead><tr><th></th><th>Código</th><th>Nome</th><th>Valor</th><th>Dias</th><th></th></tr></thead><tbody><?php $r=$obj->consultaPreparada('SELECT assCodigo,nome,valor,dias FROM assinatura ORDER BY assCodigo DESC');while($l=$r->fetch()):?><tr><td><input type="checkbox" name="assCodigo[]" value="<?php echo (int)$l['assCodigo'];?>"></td><td><?php echo (int)$l['assCodigo'];?></td><td><?php echo hs($l['nome']);?></td><td><?php echo hs($l['valor']);?></td><td><?php echo (int)$l['dias'];?></td><td><a href="assinatura.php?item=adicionar&codigo=<?php echo (int)$l['assCodigo'];?>">Editar</a></td></tr><?php endwhile;?></tbody></table></form><?php endif;?></main></div></div><?php include 'footer.php';?></body></html>
